<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TRINETRA | Contact Enquiries</title><style>:root{--ink:#eaf2ff;--muted:#91a6c7;--panel:#101d35;--line:#263c5f;--accent:#36d7e8;--bg:#071326}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 80% 0%,#173c66 0,transparent 35%),var(--bg);color:var(--ink);font:15px/1.5 Inter,Segoe UI,Arial,sans-serif}a{color:inherit;text-decoration:none}.shell{display:grid;grid-template-columns:250px 1fr;min-height:100vh}.side{padding:28px 18px;background:#09182c;border-right:1px solid var(--line);position:sticky;top:0;height:100vh}.brand{display:flex;align-items:center;gap:12px;font-weight:800;font-size:18px;letter-spacing:2px}.brand img{width:42px;height:42px;object-fit:contain}.side p{color:var(--muted);font-size:12px;margin:7px 0 28px}.nav a{display:flex;padding:12px 14px;border-radius:10px;color:#a9bad4;margin:5px 0}.nav a.active,.nav a:hover{background:#173452;color:#fff}.side-note{position:absolute;bottom:24px;color:#7186a7;font-size:11px;max-width:205px}main{padding:34px clamp(18px,4vw,58px);max-width:1500px;width:100%;margin:auto}.top{display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap;margin-bottom:24px}.eyebrow{color:var(--accent);font-size:11px;letter-spacing:2px;font-weight:800}.top h1{font-size:clamp(26px,4vw,38px);margin:5px 0}.top p,.hint{margin:0;color:var(--muted);font-size:12px}.status{border:1px solid var(--line);border-radius:30px;padding:9px 14px;color:#a8f4dc;font-size:12px}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-bottom:22px}.stat,.card{background:linear-gradient(145deg,var(--panel),#0d1a30);border:1px solid var(--line);border-radius:16px}.stat{padding:17px}.stat b{display:block;font-size:24px}.stat span{color:var(--muted);font-size:12px}.card{padding:22px;margin-bottom:18px}.field-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin:18px 0}.field{display:flex;flex-direction:column;gap:6px}label{font-size:12px;color:#b8c9e2;font-weight:650}input,select{width:100%;background:#09172b;border:1px solid #2b4265;border-radius:9px;padding:11px 12px;color:#edf5ff;font:inherit;outline:none}.actions{display:flex;flex-wrap:wrap;gap:10px;margin:14px 0}.btn{display:inline-block;border:0;border-radius:9px;padding:10px 15px;background:var(--accent);color:#061526;font-weight:800;cursor:pointer}.btn.secondary{background:#1a3151;color:#eaf2ff;border:1px solid #345174}.btn.danger{background:#542b3a;color:#ffdce4}.entry{border:1px solid #263c5f;background:#0a192e;border-radius:12px;padding:16px;margin:11px 0}.entry-head{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap}.meta{color:#91a6c7;font-size:11px;margin-top:3px}.details{display:flex;gap:16px;flex-wrap:wrap;color:#c4d2e6;font-size:12px;margin:12px 0}.empty{padding:26px;text-align:center;border:1px dashed #345174;border-radius:12px;color:#91a6c7}@media(max-width:950px){.shell{grid-template-columns:1fr}.side{position:relative;height:auto;padding:16px;border-right:0;border-bottom:1px solid var(--line)}.side-note{display:none}.nav{display:flex;overflow:auto}.nav a{white-space:nowrap}}@media(max-width:600px){main{padding:22px 14px}.stats,.field-grid{grid-template-columns:1fr}.card{padding:16px}.top{align-items:flex-start;flex-direction:column}}</style></head><body><div class="shell"><aside class="side"><div class="brand"><img src="assets/trinetra-logo.png" alt="Trinetra logo">TRINETRA</div><p>WEBSITE CONTROL CENTER</p><nav class="nav"><a href="dashboard.php">▦ Dashboard</a><a class="active" href="contact-enquiries.php">✉ Contact Enquiries</a><a class="" href="email-subscribers.php">◎ Email Subscribers</a><a href="registered-members.php">♙ Registered Website Members</a><a href="index.html" target="_blank">↗ View Website</a></nav><form method="post" action="admin-logout.php" style="margin-top:14px"><button type="submit" style="width:100%;padding:10px 13px;border:1px solid #684355;border-radius:9px;background:#2b1b2a;color:#ffdce4;font-weight:750;cursor:pointer">↪ Log Out</button></form><div class="side-note">Website communication inbox · Browser storage mode</div></aside><main><div class="top"><div><div class="eyebrow">COMMUNICATION CENTER / INBOX</div><h1>Contact Enquiries</h1><p>Review and manage messages submitted through the website contact form.</p></div><span class="status">✦ CONTACT INBOX</span></div><div class="stats"><div class="stat"><b id="total">0</b><span>Total enquiries</span></div><div class="stat"><b id="new">0</b><span>New enquiries</span></div><div class="stat"><b id="today">0</b><span>Received today</span></div></div><section class="card"><div class="field-grid"><div class="field"><label>Search messages</label><input id="search" placeholder="Name, email, company, service..."></div><div class="field"><label>Filter status</label><select id="filter"><option value="all">All enquiries</option><option>New</option><option>Reviewed</option><option>Contacted</option></select></div></div><div class="actions"><button class="btn" id="export">Export CSV</button><button class="btn secondary" id="refresh">Refresh inbox</button></div><div id="list"></div></section></main></div><script>(()=>{const K='trinetraContactEnquiries',$=x=>document.getElementById(x),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const read=()=>{try{let a=JSON.parse(localStorage.getItem(K)||'[]');return Array.isArray(a)?a:[]}catch(e){return[]}},write=a=>localStorage.setItem(K,JSON.stringify(a)),date=v=>{let d=new Date(v);return isNaN(d)?'Unknown':d.toLocaleString()};function render(){let a=read(),q=$('search').value.toLowerCase().trim(),f=$('filter').value,t=new Date().toDateString();$('total').textContent=a.length;$('new').textContent=a.filter(x=>(x.status||'New')==='New').length;$('today').textContent=a.filter(x=>new Date(x.submittedAt).toDateString()===t).length;let r=a.filter(x=>(f==='all'||(x.status||'New')===f)&&[x.name,x.email,x.phone,x.company,x.service,x.message].join(' ').toLowerCase().includes(q));$('list').innerHTML=r.length?r.map(x=>`<article class="entry"><div class="entry-head"><div><strong>${esc(x.name)}</strong><div class="meta">${esc(x.id)} · ${esc(date(x.submittedAt))}</div></div><span class="status">${esc(x.status||'New')}</span></div><div class="details"><span>✉ ${esc(x.email)}</span><span>☎ ${esc(x.phone||'Not provided')}</span><span>▣ ${esc(x.company||'Not provided')}</span></div><p style="color:#36d7e8;font-size:12px">${esc(x.service||'')} · ${esc(x.timeline||'No timeline')}</p><p style="white-space:pre-wrap;color:#c4d2e6;font-size:13px">${esc(x.message)}</p><div class="actions"><button class="btn secondary" data-status="${esc(x.id)}">${(x.status||'New')==='New'?'Mark reviewed':x.status==='Reviewed'?'Mark contacted':'Mark new'}</button><a class="btn secondary" href="mailto:${encodeURIComponent(x.email||'')}">Reply by email</a><button class="btn danger" data-del="${esc(x.id)}">Delete</button></div></article>`).join(''):'<div class="empty">No contact enquiries found yet.</div>';$('list').querySelectorAll('[data-status]').forEach(b=>b.onclick=()=>{let z=read(),x=z.find(v=>v.id===b.dataset.status);if(x){x.status=x.status==='New'?'Reviewed':x.status==='Reviewed'?'Contacted':'New';write(z);render()}});$('list').querySelectorAll('[data-del]').forEach(b=>b.onclick=()=>{if(confirm('Permanently delete this enquiry?')){write(read().filter(x=>x.id!==b.dataset.del));render()}})}$('search').oninput=render;$('filter').onchange=render;$('refresh').onclick=render;$('export').onclick=()=>{let a=read(),cols=['id','submittedAt','status','name','email','phone','company','service','timeline','message'];if(!a.length)return alert('No enquiries to export.');let csv=[cols.join(','),...a.map(r=>cols.map(k=>'"'+String(r[k]??'').replace(/"/g,'""')+'"').join(','))].join('\r\n'),u=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv'})),l=document.createElement('a');l.href=u;l.download='trinetra-contact-enquiries.csv';l.click();URL.revokeObjectURL(u)};addEventListener('storage',e=>{if(e.key===K)render()});render()})();</script></body></html>